var R = 8.314; // J/(mol·K)
function rateConstant(A, Ea, T){ if(!(T>0)) return NaN; return A*Math.exp(-Ea/(R*T)); }
function activationEnergy(k1, T1, k2, T2){ if(!(T1>0)||!(T2>0)||k1<=0||k2<=0) return NaN; return -R*Math.log(k2/k1)/(1/T2 - 1/T1); }
var EXPORTS = { rateConstant:rateConstant, activationEnergy:activationEnergy, R:R };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ActivationEnergyForgePure = EXPORTS; }
